import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.gmyryY1Z.js";const h=JSON.parse('{"title":"Apps Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/apps/index.md","filePath":"en/apps/index.md","lastUpdated":null}'),d={name:"en/apps/index.md"};function n(s,e,r,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="apps-overview" tabindex="-1">Apps Overview <a class="header-anchor" href="#apps-overview" aria-label="Permalink to &quot;Apps Overview&quot;">​</a></h1><p>Fast Vue3 contains 5 independent UI ecosystem apps. Each app:</p><ul><li>Has its own routing system</li><li>Has its own layout and theme</li><li>Shares all <code>packages/*</code> infrastructure</li><li>Runs on a dedicated port</li></ul><h2 id="app-list" tabindex="-1">App List <a class="header-anchor" href="#app-list" aria-label="Permalink to &quot;App List&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>UI Framework</th><th>Port</th><th>Command</th></tr></thead><tbody><tr><td>web-antd</td><td>Ant Design Vue 4.x</td><td>3001</td><td><code>pnpm dev:antd</code></td></tr><tr><td>web-ele</td><td>Element Plus 2.x</td><td>3002</td><td><code>pnpm dev:ele</code></td></tr><tr><td>web-naive</td><td>Naive UI 2.x</td><td>3003</td><td><code>pnpm dev:naive</code></td></tr><tr><td>web-arco</td><td>Arco Design Vue 2.x</td><td>3004</td><td><code>pnpm dev:arco</code></td></tr><tr><td>web-tdesign</td><td>TDesign Vue Next 1.x</td><td>3005</td><td><code>pnpm dev:tdesign</code></td></tr></tbody></table><h2 id="common-features" tabindex="-1">Common Features <a class="header-anchor" href="#common-features" aria-label="Permalink to &quot;Common Features&quot;">​</a></h2><p>All apps implement the following:</p><h3 id="authentication-flow" tabindex="-1">Authentication Flow <a class="header-anchor" href="#authentication-flow" aria-label="Permalink to &quot;Authentication Flow&quot;">​</a></h3><ol><li>Unauthenticated user → auto-redirect to <code>/login</code></li><li>Login success → fetch user profile → enter main layout</li><li>Logout → clear token → redirect to <code>/login</code></li></ol><p>Authentication logic is provided by <code>@fast-vue3/access</code>&#39;s <code>setupAccessGuard</code>.</p><h3 id="main-layout" tabindex="-1">Main Layout <a class="header-anchor" href="#main-layout" aria-label="Permalink to &quot;Main Layout&quot;">​</a></h3><p>All apps&#39; <code>src/views/index.vue</code> includes:</p><ul><li>Collapsible sidebar navigation</li><li>Top header (user info + logout)</li><li>Content area (<code>&lt;RouterView /&gt;</code>)</li></ul><h3 id="file-based-routing" tabindex="-1">File-based Routing <a class="header-anchor" href="#file-based-routing" aria-label="Permalink to &quot;File-based Routing&quot;">​</a></h3><p>Using <code>unplugin-vue-router</code>, <code>.vue</code> files under <code>src/views/</code> are automatically mapped to routes.</p><h3 id="mock-api" tabindex="-1">Mock API <a class="header-anchor" href="#mock-api" aria-label="Permalink to &quot;Mock API&quot;">​</a></h3><p>Each app&#39;s <code>mock/</code> directory provides:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/user/login    → { token: &#39;mock-token-xxx&#39; }</span></span>
<span class="line"><span>GET  /api/user/profile  → { userName, avatar, role }</span></span>
<span class="line"><span>POST /api/user/logout   → {}</span></span></code></pre></div><h2 id="ui-isolation" tabindex="-1">UI Isolation <a class="header-anchor" href="#ui-isolation" aria-label="Permalink to &quot;UI Isolation&quot;">​</a></h2><p>UI components from different frameworks do not interfere with each other. Auto-imports are scoped to each app via the resolver in <code>vite.config.ts</code>.</p><h2 id="adding-a-new-ui-ecosystem" tabindex="-1">Adding a New UI Ecosystem <a class="header-anchor" href="#adding-a-new-ui-ecosystem" aria-label="Permalink to &quot;Adding a New UI Ecosystem&quot;">​</a></h2><p>See <a href="./add-new">Add New UI Library</a>.</p>`,22)])])}const m=a(d,[["render",n]]);export{h as __pageData,m as default};
